<!doctype html>
<html lang="zh-CN" data-theme="light" data-palette="color">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>杨氏双缝干涉仿真</title>
    <meta http-equiv="Content-Security-Policy" content="default-src 'none'; connect-src 'none'; frame-src 'none'; object-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; base-uri 'none'; form-action 'none'">
    <style id="phy-sim-style">
        :root {
            --bg-color: #ffffff;
            --text-color: #333333;
            --panel-bg: #f5f5f5;
            --border-color: #cccccc;
            --accent-color: #007bff;
            --canvas-bg: #ffffff;
            --modal-backdrop: rgba(0,0,0,0.5);
            --font-family: system-ui, -apple-system, sans-serif;
            --marker-bright: #ff6600;
            --marker-dark: #0066cc;
        }
        [data-theme="dark"] {
            --bg-color: #1a1a2e;
            --text-color: #e0e0e0;
            --panel-bg: #16213e;
            --border-color: #444;
            --accent-color: #4da3ff;
            --canvas-bg: #0a0a0a;
            --modal-backdrop: rgba(0,0,0,0.8);
            --marker-bright: #ffaa00;
            --marker-dark: #66ccff;
        }
        * { box-sizing: border-box; }
        html, body { margin: 0; padding: 0; height: 100%; }
        body {
            font-family: var(--font-family);
            background: var(--bg-color);
            color: var(--text-color);
            display: flex;
            flex-direction: column;
            overflow: hidden;
            padding: 12px;
            transition: background 0.3s, color 0.3s;
        }
        header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-shrink: 0;
            margin-bottom: 10px;
        }
        h1 { margin: 0; font-size: 1.3rem; }
        .toolbar button {
            background: var(--panel-bg);
            border: 1px solid var(--border-color);
            color: var(--text-color);
            padding: 5px 10px;
            cursor: pointer;
            border-radius: 4px;
            margin-left: 4px;
            font-size: 0.85rem;
        }
        .toolbar button:hover { opacity: 0.8; }
        main {
            display: grid;
            grid-template-columns: 280px 1fr;
            gap: 12px;
            flex: 1;
            min-height: 0;
        }
        @media (max-width: 768px) {
            main { grid-template-columns: 1fr; grid-template-rows: auto 1fr; }
            body { overflow: auto; }
        }
        .panel {
            background: var(--panel-bg);
            border: 1px solid var(--border-color);
            border-radius: 8px;
            padding: 12px;
            display: flex;
            flex-direction: column;
            overflow-y: auto;
        }
        .panel-title {
            font-weight: bold;
            margin-bottom: 10px;
            border-bottom: 1px solid var(--border-color);
            padding-bottom: 4px;
            font-size: 0.85rem;
            letter-spacing: 0.5px;
        }
        .control-group { margin-bottom: 12px; }
        .label-row {
            display: flex;
            justify-content: space-between;
            margin-bottom: 3px;
            font-size: 0.82rem;
        }
        input[type=range] { width: 100%; accent-color: var(--accent-color); cursor: pointer; }
        .markers-container {
            position: relative;
            height: 14px;
            margin-top: 2px;
        }
        .markers-container .marker {
            position: absolute;
            top: 0;
            width: 10px;
            height: 10px;
            border-radius: 50%;
            transform: translateX(-50%);
        }
        .markers-container .marker.bright, .markers-container .marker[data-kind="bright"] {
            background: var(--marker-bright);
            border: 2px solid var(--marker-bright);
        }
        .markers-container .marker.dark, .markers-container .marker[data-kind="dark"] {
            background: transparent;
            border: 2px solid var(--marker-dark);
        }
        .canvas-wrapper {
            display: flex;
            flex-direction: column;
            gap: 10px;
            flex: 1;
            min-height: 0;
        }
        .canvas-box {
            flex: 1;
            position: relative;
            min-height: 120px;
            border: 1px solid var(--border-color);
            border-radius: 4px;
            overflow: hidden;
            background: var(--canvas-bg);
        }
        .canvas-box .panel-title {
            position: absolute;
            top: 4px;
            left: 8px;
            z-index: 2;
            border: none;
            margin: 0;
            padding: 0;
            font-size: 0.75rem;
            opacity: 0.7;
        }
        canvas { display: block; width: 100%; height: 100%; }
        #intensityCanvas:focus { outline: 2px solid var(--accent-color); }
        #intensity-tooltip {
            position: absolute;
            background: rgba(0,0,0,0.85);
            color: #fff;
            padding: 4px 8px;
            border-radius: 4px;
            font-size: 0.75rem;
            pointer-events: none;
            z-index: 10;
            white-space: nowrap;
            display: none;
        }
        #principle-modal {
            position: fixed;
            top: 0; left: 0; right: 0; bottom: 0;
            background: var(--modal-backdrop);
            display: none;
            justify-content: center;
            align-items: center;
            z-index: 1000;
            padding: 16px;
        }
        #principle-modal.open { display: flex; }
        .modal-inner {
            background: var(--bg-color);
            color: var(--text-color);
            border-radius: 8px;
            max-width: 600px;
            width: 100%;
            padding: 20px;
            box-shadow: 0 4px 20px rgba(0,0,0,0.3);
            max-height: 90vh;
            overflow-y: auto;
        }
        .modal-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 12px;
        }
        .modal-header h2 { margin: 0; font-size: 1.1rem; }
        #modal-close-button {
            background: none;
            border: none;
            font-size: 1.5rem;
            cursor: pointer;
            color: var(--text-color);
            line-height: 1;
        }
        .svg-container {
            width: 100%;
            border: 1px dashed var(--border-color);
            border-radius: 4px;
            margin-bottom: 12px;
            padding: 8px;
        }
        .modal-inner p { font-size: 0.88rem; line-height: 1.6; }
        body[data-compact="true"] .panel { padding: 8px; }
        body[data-compact="true"] h1 { font-size: 1.1rem; }
        body[data-compact="true"] .control-group { margin-bottom: 8px; }
    </style>
</head>
<body data-compact="false">
    <header>
        <h1>杨氏双缝干涉仿真</h1>
        <div class="toolbar">
            <button id="reset-button" title="重置参数">重置</button>
            <button id="theme-button" title="切换主题">主题</button>
            <button id="palette-button" title="切换配色">配色</button>
            <button id="principle-button" title="原理说明">原理</button>
        </div>
    </header>
    <main>
        <section class="panel" aria-label="参数调控">
            <div class="panel-title">参数调控</div>
            <div class="control-group">
                <div class="label-row">
                    <label for="wavelength">波长 λ</label>
                    <output id="wavelength-output">550 nm</output>
                </div>
                <input type="range" id="wavelength" min="380" max="750" value="550" step="1">
                <div class="markers-container" id="wavelength-markers"></div>
            </div>
            <div class="control-group">
                <div class="label-row">
                    <label for="slitSeparation">缝间距 d</label>
                    <output id="slitSeparation-output">5000 nm</output>
                </div>
                <input type="range" id="slitSeparation" min="1000" max="10000" value="5000" step="10">
                <div class="markers-container" id="slitSeparation-markers"></div>
            </div>
            <div class="control-group">
                <div class="label-row">
                    <label for="slitWidth">缝宽 a</label>
                    <output id="slitWidth-output">1000 nm</output>
                </div>
                <input type="range" id="slitWidth" min="200" max="3000" value="1000" step="10">
            </div>
            <div class="control-group">
                <div class="label-row">
                    <label for="screenDistance">屏距 Dsim</label>
                    <output id="screenDistance-output">50</output>
                </div>
                <input type="range" id="screenDistance" min="1" max="100" value="50" step="1">
            </div>
            <div class="control-group">
                <div class="label-row">
                    <label for="zoom">缩放 Z</label>
                    <output id="zoom-output">×1.0</output>
                </div>
                <input type="range" id="zoom" min="1" max="5" value="1" step="0.1">
            </div>
        </section>
        <section class="panel" aria-label="可视化区域">
            <div class="canvas-wrapper">
                <div class="canvas-box">
                    <div class="panel-title">干涉条纹图样</div>
                    <canvas id="interferenceCanvas"></canvas>
                </div>
                <div class="canvas-box">
                    <div class="panel-title">归一化光强</div>
                    <canvas id="intensityCanvas" tabindex="0"></canvas>
                    <div id="intensity-tooltip" role="tooltip" aria-hidden="true"></div>
                </div>
            </div>
        </section>
    </main>
    <div id="principle-modal" aria-hidden="true">
        <div class="modal-inner" role="dialog" aria-modal="true" aria-labelledby="modal-title">
            <div class="modal-header">
                <h2 id="modal-title">杨氏双缝干涉原理</h2>
                <button id="modal-close-button" aria-label="关闭">×</button>
            </div>
            <div class="svg-container">
                <svg viewBox="0 0 400 180" width="100%" height="160" aria-label="双缝干涉几何示意图">
                    <circle cx="40" cy="90" r="4" fill="currentColor"/>
                    <text x="25" y="80" font-size="12" fill="currentColor">S</text>
                    <line x1="140" y1="10" x2="140" y2="70" stroke="currentColor" stroke-width="2"/>
                    <line x1="140" y1="110" x2="140" y2="170" stroke="currentColor" stroke-width="2"/>
                    <text x="125" y="95" font-size="11" fill="currentColor">d</text>
                    <line x1="340" y1="10" x2="340" y2="170" stroke="currentColor" stroke-width="3"/>
                    <text x="345" y="95" font-size="11" fill="currentColor">屏</text>
                    <line x1="40" y1="90" x2="140" y2="90" stroke="currentColor" stroke-width="1" stroke-dasharray="4,3" opacity="0.5"/>
                    <line x1="140" y1="70" x2="340" y2="60" stroke="currentColor" stroke-width="1" opacity="0.6"/>
                    <line x1="140" y1="110" x2="340" y2="120" stroke="currentColor" stroke-width="1" opacity="0.6"/>
                    <text x="200" y="160" font-size="11" fill="currentColor">D (屏距)</text>
                    <line x1="150" y1="150" x2="330" y2="150" stroke="currentColor" stroke-width="1" marker-end="none"/>
                </svg>
            </div>
            <p>单色光通过间距为 d 的双缝后，在距离 D 的屏幕上形成干涉条纹。归一化光强为 I<sub>N</sub>(η) = sinc²(πaη/λ)·cos²(πdη/λ)，其中 sinc(t)=sin(t)/t。单缝衍射包络调制双缝干涉条纹。</p>
        </div>
    </div>
    <script id="phy-sim-script">
    (function() {
        'use strict';
        var PARAM_KEYS = ['wavelength','slitSeparation','slitWidth','screenDistance','zoom'];
        var DEFAULTS = {wavelength:550,slitSeparation:5000,slitWidth:1000,screenDistance:50,zoom:1};
        var LIMITS = {wavelength:[380,750],slitSeparation:[1000,10000],slitWidth:[200,3000],screenDistance:[1,100],zoom:[1,5]};
        var ETA_REF = 0.11;

        var params = {};
        var hoverX = null;
        var readyResolve = null;
        var readyPromise = new Promise(function(r){ readyResolve = r; });
        var firstFrameDone = false;

        function clamp(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }

        function normalize(partial) {
            var out = {};
            for (var i = 0; i < PARAM_KEYS.length; i++) {
                var k = PARAM_KEYS[i];
                var v = (partial && partial[k] !== undefined) ? Number(partial[k]) : DEFAULTS[k];
                if (!isFinite(v)) v = DEFAULTS[k];
                v = clamp(v, LIMITS[k][0], LIMITS[k][1]);
                out[k] = v;
            }
            if (out.slitWidth > out.slitSeparation) out.slitWidth = out.slitSeparation;
            return out;
        }

        function sinc(t) { return t === 0 ? 1 : Math.sin(t) / t; }

        function intensityAtEta(eta, p) {
            p = p || params;
            var lam = p.wavelength, a = p.slitWidth, d = p.slitSeparation;
            var t1 = Math.PI * a * eta / lam;
            var t2 = Math.PI * d * eta / lam;
            var s = sinc(t1);
            return s * s * Math.cos(t2) * Math.cos(t2);
        }

        function etaFromX(x, cssW, p) {
            p = p || params;
            return (x - cssW / 2) / (4 * p.screenDistance * p.zoom);
        }

        function wavelengthToRGB(wl) {
            var r=0,g=0,b=0;
            if(wl>=380&&wl<440){r=-(wl-440)/60;b=1;}
            else if(wl>=440&&wl<490){g=(wl-440)/50;b=1;}
            else if(wl>=490&&wl<510){g=1;b=-(wl-510)/20;}
            else if(wl>=510&&wl<580){r=(wl-510)/70;g=1;}
            else if(wl>=580&&wl<645){r=1;g=-(wl-645)/65;}
            else if(wl>=645&&wl<=750){r=1;}
            var f=1;
            if(wl>=380&&wl<420)f=0.3+0.7*(wl-380)/40;
            else if(wl>700&&wl<=750)f=0.3+0.7*(750-wl)/50;
            return [Math.round(r*f*255),Math.round(g*f*255),Math.round(b*f*255)];
        }

        function getCriticalMarkers(p) {
            p = p || params;
            var result = {wavelength:[],slitSeparation:[]};
            var d = p.slitSeparation, lam = p.wavelength;
            // wavelength markers: d*ETA_REF/lambda = m (bright) or m+0.5 (dark)
            for (var m = 1; m <= 50; m++) {
                var lv = d * ETA_REF / m;
                if (lv >= LIMITS.wavelength[0] && lv <= LIMITS.wavelength[1]) {
                    result.wavelength.push({kind:'bright',order:m,value:Math.round(lv*100)/100});
                }
            }
            for (var m2 = 0; m2 <= 50; m2++) {
                var lv2 = d * ETA_REF / (m2 + 0.5);
                if (lv2 >= LIMITS.wavelength[0] && lv2 <= LIMITS.wavelength[1]) {
                    result.wavelength.push({kind:'dark',order:m2+0.5,value:Math.round(lv2*100)/100});
                }
            }
            // slitSeparation markers: d*ETA_REF/lambda = m or m+0.5
            for (var m3 = 1; m3 <= 100; m3++) {
                var dv = lam * m3 / ETA_REF;
                if (dv >= LIMITS.slitSeparation[0] && dv <= LIMITS.slitSeparation[1]) {
                    result.slitSeparation.push({kind:'bright',order:m3,value:Math.round(dv*100)/100});
                }
            }
            for (var m4 = 0; m4 <= 100; m4++) {
                var dv2 = lam * (m4 + 0.5) / ETA_REF;
                if (dv2 >= LIMITS.slitSeparation[0] && dv2 <= LIMITS.slitSeparation[1]) {
                    result.slitSeparation.push({kind:'dark',order:m4+0.5,value:Math.round(dv2*100)/100});
                }
            }
            return result;
        }

        function renderMarkers() {
            var cm = getCriticalMarkers(params);
            var wlCont = document.getElementById('wavelength-markers');
            var dsCont = document.getElementById('slitSeparation-markers');
            wlCont.innerHTML = '';
            dsCont.innerHTML = '';
            var wlMin = LIMITS.wavelength[0], wlMax = LIMITS.wavelength[1];
            var dsMin = LIMITS.slitSeparation[0], dsMax = LIMITS.slitSeparation[1];
            cm.wavelength.forEach(function(mk) {
                var el = document.createElement('span');
                el.className = 'marker ' + mk.kind;
                el.setAttribute('data-kind', mk.kind);
                var pct = (mk.value - wlMin) / (wlMax - wlMin) * 100;
                el.style.left = pct + '%';
                el.title = mk.kind + ' m=' + mk.order + ' λ=' + mk.value + 'nm';
                wlCont.appendChild(el);
            });
            cm.slitSeparation.forEach(function(mk) {
                var el = document.createElement('span');
                el.className = 'marker ' + mk.kind;
                el.setAttribute('data-kind', mk.kind);
                var pct = (mk.value - dsMin) / (dsMax - dsMin) * 100;
                el.style.left = pct + '%';
                el.title = mk.kind + ' m=' + mk.order + ' d=' + mk.value + 'nm';
                dsCont.appendChild(el);
            });
        }

        function getCanvasCSSSize(canvas) {
            var rect = canvas.getBoundingClientRect();
            return { w: rect.width, h: rect.height };
        }

        function setupCanvas(canvas) {
            var dpr = window.devicePixelRatio || 1;
            var rect = canvas.getBoundingClientRect();
            var w = Math.round(rect.width * dpr);
            var h = Math.round(rect.height * dpr);
            if (canvas.width !== w || canvas.height !== h) {
                canvas.width = w;
                canvas.height = h;
            }
            var ctx = canvas.getContext('2d');
            ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
            return { ctx: ctx, cssW: rect.width, cssH: rect.height, dpr: dpr };
        }

        function renderPattern() {
            var canvas = document.getElementById('interferenceCanvas');
            var info = setupCanvas(canvas);
            var ctx = info.ctx, cssW = info.cssW, cssH = info.cssH;
            var palette = document.documentElement.getAttribute('data-palette') || 'color';
            var gamma = 0.8;
            ctx.clearRect(0, 0, cssW, cssH);
            var rgb = wavelengthToRGB(params.wavelength);
            for (var x = 0; x < cssW; x++) {
                var eta = etaFromX(x, cssW, params);
                var I = intensityAtEta(eta, params);
                I = clamp(I, 0, 1);
                if (palette === 'grayscale') {
                    var bright = Math.pow(I, gamma);
                    var v = Math.round(bright * 255);
                    ctx.fillStyle = 'rgb(' + v + ',' + v + ',' + v + ')';
                } else {
                    var r2 = Math.round(rgb[0] * I);
                    var g2 = Math.round(rgb[1] * I);
                    var b2 = Math.round(rgb[2] * I);
                    ctx.fillStyle = 'rgb(' + r2 + ',' + g2 + ',' + b2 + ')';
                }
                ctx.fillRect(x, 0, 1, cssH);
            }
            if (hoverX !== null) {
                ctx.strokeStyle = 'rgba(255,255,0,0.8)';
                ctx.lineWidth = 1.5;
                ctx.beginPath();
                ctx.moveTo(hoverX, 0);
                ctx.lineTo(hoverX, cssH);
                ctx.stroke();
            }
        }

        function renderCurve() {
            var canvas = document.getElementById('intensityCanvas');
            var info = setupCanvas(canvas);
            var ctx = info.ctx, cssW = info.cssW, cssH = info.cssH;
            var theme = document.documentElement.getAttribute('data-theme') || 'light';
            var marginV = 20;
            var plotH = cssH - marginV * 2;
            ctx.clearRect(0, 0, cssW, cssH);
            // axes
            ctx.strokeStyle = theme === 'dark' ? '#555' : '#ccc';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(0, cssH - marginV);
            ctx.lineTo(cssW, cssH - marginV);
            ctx.stroke();
            // curve
            ctx.strokeStyle = theme === 'dark' ? '#4da3ff' : '#0055cc';
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            var first = true;
            for (var x = 0; x <= cssW; x += 0.5) {
                var eta = etaFromX(x, cssW, params);
                var I = intensityAtEta(eta, params);
                var y = cssH - marginV - I * plotH;
                if (first) { ctx.moveTo(x, y); first = false; }
                else { ctx.lineTo(x, y); }
            }
            ctx.stroke();
            // hover indicator
            if (hoverX !== null) {
                ctx.strokeStyle = 'rgba(255,200,0,0.9)';
                ctx.lineWidth = 1.5;
                ctx.beginPath();
                ctx.moveTo(hoverX, 0);
                ctx.lineTo(hoverX, cssH);
                ctx.stroke();
            }
        }

        function render() {
            renderPattern();
            renderCurve();
            renderMarkers();
            if (!firstFrameDone) {
                firstFrameDone = true;
                if (readyResolve) readyResolve();
            }
        }

        function updateOutputs() {
            document.getElementById('wavelength-output').textContent = params.wavelength + ' nm';
            document.getElementById('slitSeparation-output').textContent = params.slitSeparation + ' nm';
            document.getElementById('slitWidth-output').textContent = params.slitWidth + ' nm';
            document.getElementById('screenDistance-output').textContent = params.screenDistance;
            document.getElementById('zoom-output').textContent = '×' + params.zoom.toFixed(1);
        }

        function syncInputs() {
            PARAM_KEYS.forEach(function(k) {
                var el = document.getElementById(k);
                if (el) el.value = params[k];
            });
            updateOutputs();
        }

        function setParams(partial) {
            params = normalize(partial);
            syncInputs();
            render();
        }

        function getParams() {
            var copy = {};
            PARAM_KEYS.forEach(function(k){ copy[k] = params[k]; });
            return copy;
        }

        function readURL() {
            var q = {};
            try {
                var sp = new URLSearchParams(window.location.search);
                PARAM_KEYS.forEach(function(k) {
                    if (sp.has(k)) q[k] = sp.get(k);
                });
                if (sp.has('theme')) q.theme = sp.get('theme');
                if (sp.has('palette')) q.palette = sp.get('palette');
                if (sp.has('compact')) q.compact = sp.get('compact');
            } catch(e) {}
            return q;
        }

        function applyURL() {
            var q = readURL();
            var p = {};
            PARAM_KEYS.forEach(function(k) {
                if (q[k] !== undefined) p[k] = Number(q[k]);
            });
            params = normalize(p);
            var html = document.documentElement;
            if (q.theme === 'dark' || q.theme === 'light') html.setAttribute('data-theme', q.theme);
            if (q.palette === 'grayscale' || q.palette === 'color') html.setAttribute('data-palette', q.palette);
            if (q.compact === '1') document.body.setAttribute('data-compact', 'true');
            else document.body.setAttribute('data-compact', 'false');
        }

        function showTooltip(x, cssW) {
            var tooltip = document.getElementById('intensity-tooltip');
            var eta = etaFromX(x, cssW, params);
            var I = intensityAtEta(eta, params);
            tooltip.textContent = 'η=' + eta.toFixed(5) + '  I_N=' + (I * 100).toFixed(1) + '%';
            tooltip.style.display = 'block';
            var box = document.getElementById('intensityCanvas').getBoundingClientRect();
            var tx = clamp(x, 40, cssW - 40);
            tooltip.style.left = tx + 'px';
            tooltip.style.top = '5px';
        }

        function hideTooltip() {
            document.getElementById('intensity-tooltip').style.display = 'none';
        }

        function init() {
            applyURL();
            syncInputs();

            PARAM_KEYS.forEach(function(k) {
                var el = document.getElementById(k);
                if (el) {
                    el.addEventListener('input', function() {
                        var obj = {};
                        obj[k] = Number(el.value);
                        params = normalize(obj);
